INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "李继勋（后蜀将领）", "aliases": ["李繼勳（後蜀將領）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀左千牛卫上将军。947年正月癸丑，孟昶任命他为秦州宣慰使。使用国别限定身份，暂未与后周宋初同名将领合并，生卒年未载。", "biography": null, "status": "draft", "id": "2524497d-8a5b-5e26-81cb-c5fc6e3b1d1f"}, {"name": "刘景（后蜀兴州刺史）", "aliases": ["劉景（後蜀興州刺史）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后蜀兴州刺史，947年二月与李继勋攻取固镇。生卒年未载；不与刘景岩等姓名相近的人物合并。", "biography": null, "status": "draft", "id": "6d4e2773-1d10-521c-87e2-06156e0008d1"}, {"name": "何重建", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋曹州防御使，云州、朔州一带胡人。942年受命援救延州，二月被任命为彰武留后。生卒年未载。", "biography": null, "status": "draft", "id": "32fa2f01-0372-5b5b-83b5-c66e445ba1c1"}, {"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "史弘肇", "aliases": ["史宏肇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "荥泽人，947年二月任刘知远的武节都指挥使，奉命在球场集合各军，宣布出兵日期。《旧五代史》亦有史宏肇的字形。生卒年暂未录入。", "biography": null, "status": "draft", "id": "c36d0d69-d2db-5ee8-9bf6-80791eb21dda"}, {"name": "张彦威", "aliases": ["張彥威"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "潞城人，947年二月任河东行军司马，与其他将吏多次上书劝刘知远称帝。生卒年未载。", "biography": null, "status": "draft", "id": "e0b16d41-9e50-528a-93cd-861c7eed8115"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "杨邠", "aliases": ["楊邠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冠氏人，947年二月任河东都押牙，与郭威共同劝刘知远接受称帝建议。生卒年暂未录入。", "biography": null, "status": "draft", "id": "eede7986-584c-5c2a-9c1c-39a3959f1291"}, {"name": "刘愿（947年契丹将）", "aliases": ["劉願（947年契丹將）", "劉愿（947年契丹將）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹将领，被任命为保义节度副使。947年二月庚午，王晏等在陕州杀死他。《宋史》姓名写作劉愿，保留不同底本字形，不与其他同名作者合并。生年未载。", "biography": null, "status": "draft", "id": "64330294-72c4-5b43-aef0-281a7a7d795a"}, {"name": "王晏", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "徐州人，947年二月任奉国都头，与赵晖、侯章谋划杀死契丹将刘愿，率数名壮士夜入府署、取库中兵器。生卒年暂未录入。", "biography": null, "status": "draft", "id": "030a26f1-62e3-5876-92b4-923b763723f0"}, {"name": "赵晖（后汉将领）", "aliases": ["趙暉（後漢將領）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "澶州人，947年二月在陕州与王晏、侯章谋划反抗契丹，刘愿被杀后获推为留后。与887年被部下杀死的上元赵晖不是同一人。生卒年暂未录入。", "biography": null, "status": "draft", "id": "ed9f97dd-d560-5635-bf04-6575c39075b8"}, {"name": "侯章", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，947年二月任都头，在陕州与王晏、赵晖共同谋划反抗契丹。生卒年暂未录入。", "biography": null, "status": "draft", "id": "aafc9da4-682f-5473-bedf-46c919bc77c8"}, {"name": "崔延琛", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：崔延琛。", "biography": null, "status": "draft", "id": "27ee3209-63ad-56d7-88d7-6384a07d78ae"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

